import {DATA} from './data.js';
import {defaults,generate,blankBattle,replay,availability,damageExpression,declaration,addEvent,validateImport,baseEffort,multithrow} from './engine.js';
const $=s=>document.querySelector(s);
const assetBase=new URL('./assets/',import.meta.url).href;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=v=>Number(v)||0;
const signed=v=>v>=0?'+'+v:String(v);
const KEY='ember-monsterforge-v1',LIB='ember-monsterforge-bestiary-v1';
let state={version:1,config:{...defaults},battle:blankBattle(),hunt:{location:'a ruined aqueduct',incident:'caravans have stopped returning',objective:'Capture',tracks:0,nature:0,weakness:0,preparations:''},notes:''};
let library=[],profile,live,view='forge',toastTimer,decl={format:'plain',target:'',noEarth:false};
try{const saved=localStorage.getItem(KEY);if(saved)state=validateImport(JSON.parse(saved));library=JSON.parse(localStorage.getItem(LIB)||'[]');if(!Array.isArray(library))library=[];else library=library.filter(o=>{try{validateImport(o);return true;}catch{return false;}});document.documentElement.dataset.theme=localStorage.getItem('mf-theme')||'dark';document.body.classList.toggle('large',localStorage.getItem('mf-large')==='true');}catch{toast('Saved data could not be loaded. Import a backup to restore it.');}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),5500);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));localStorage.setItem(LIB,JSON.stringify(library));$('#save-state').textContent='Saved on this device';}catch{$('#save-state').textContent='Save unavailable — export a backup';toast('Browser storage is unavailable or full. Export JSON to keep this sheet.');}}
function refresh(){profile=generate(state.config);live=replay(profile,state.battle);}
function field(id,label,value,type='text',extra=''){return `<div class="field"><label for="${id}">${label}</label><input id="${id}" name="${id}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function select(id,label,value,values,extra=''){return `<div class="field"><label for="${id}">${label}</label><select id="${id}" name="${id}" ${extra}>${values.map(v=>`<option ${v===value?'selected':''}>${esc(v)}</option>`).join('')}</select></div>`;}
function intro(kicker,title,text){return `<section class="intro"><img class="monster-art" src="${assetBase}monster.svg" alt=""><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${text}</p></section>`;}
function panel(title,body,extra=''){return `<section class="panel ${extra}"><div class="panelhead"><h2>${title}</h2></div><div class="panelbody">${body}</div></section>`;}
function metrics(o){return `<dl class="metrics">${Object.entries(o).map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>`;}
function tools(){return `<div class="buttons no-print"><button data-do="save-monster">Save to bestiary</button><button data-do="export">Export JSON</button><button data-do="share">Copy share link</button><button data-do="print">Print sheet</button></div>`;}
function warning(){return profile.warnings.length?`<div class="notice"><strong>Review this profile</strong><ul>${profile.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></div>`:'';}
function emblem(group,name,extra=''){return `<img class="emblem ${extra}" src="${assetBase}${group}/${encodeURIComponent(name.toLowerCase())}.svg" alt="" width="64" height="64">`;}
function profilePanel(){return `<section class="panel"><div class="profilehead">${emblem('tribes',state.config.tribe,'profile-emblem')}<span class="badge red">${esc(state.config.threat)}</span> <span class="badge">${esc(state.config.tribe)}</span><h2>${esc(profile.name)}</h2><p class="muted">${emblem('classes',profile.role,'class-emblem')} ${esc(profile.role)} · ${esc(profile.mutation)} · ${esc(profile.element)}<br>${esc(profile.appearance)} / ${esc(profile.terrain)}</p></div><div class="stats">${Object.entries(profile.stats).map(([k,v])=>`<div class="stat"><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><div class="panelbody">${metrics({'Accuracy':signed(profile.accuracy),'Defense bonus':signed(profile.defense),'Injury gate':profile.gate,'Physical DB':profile.pdb,'Ninjutsu DB':profile.ndb,'Move yd / IC':profile.movement,'Physical DR':profile.dr,'Initiative':signed(profile.initiative),'Save TN':profile.save})}<div class="trait"><strong>${esc(profile.mutation)}</strong>${esc(profile.trait)}</div><p><small>COUNTERPLAY</small><br>${esc(profile.counter)}</p><p><small>BEHAVIOUR</small><br>${esc(profile.behavior)}</p>${warning()}<details><summary>Additional combat values</summary><div class="sectiongap">${metrics({'Damage budget':profile.budget,'Six-gate capacity':profile.gate*6,'Break threshold':profile.breakThreshold,'Grapple Offense':profile.grappleOff,'Grapple Def bonus':profile.grappleDef,'Mutation budget':profile.mutationBudget,...profile.skills})}<p class="formhint">Party size scales durability. Enemy count reduces ordinary attack dice; jutsu retain their printed dice.</p></div></details>${tools()}</div></section>`;}
function forge(){const c=state.config;return intro('01 / CREATURE DESIGN','Forge the <em>untamed.</em>','Choose a tribe, shape the creature, and prepare its hunt.')+`<div class="split"><section class="panel no-print"><div class="panelhead"><h2><span class="panelnumber">01</span>Creature details</h2><span class="badge">FIXED SEED</span></div><form id="forge-form" class="panelbody"><div class="formgrid">${select('tribe','Monster tribe',c.tribe,DATA.tribes.map(t=>t[0]),'required')}${select('threat','Threat class',c.threat,DATA.threats.map(r=>r[0]))}${field('xp','Average hunter XP',c.xp,'number','min="0" max="100000" step="1" required')}${field('hunters','Hunters in party',c.hunters,'number','min="1" max="100" step="1" required')}${field('enemies','Enemies in encounter',c.enemies,'number','min="1" max="100" step="1" required')}${select('intensity','Intensity',c.intensity,['Conservative','Standard','High'])}<div class="full">${field('name','Custom name (optional)',c.name,'text','maxlength="160" placeholder="Use the generated name"')}</div>${field('seed','Generation seed',c.seed,'number','min="1" max="999999" step="1" required')}${select('casting','Jutsu permission',c.casting,['Auto','Never','Instinctive','Adept'])}</div><details class="sectiongap"><summary>Body, combat class & mutation</summary><p class="formhint">Auto stays within the chosen tribe. Manual choices outside its pool are flagged for review.</p><div class="formgrid sectiongap">${select('body','Body',c.body,['Auto',...DATA.bodies.map(r=>r[0])])}${select('role','Combat class',c.role,['Auto',...DATA.roles.map(r=>r[0])])}${select('mutation','Mutation',c.mutation,['Auto',...DATA.mutations.map(r=>r[0])])}${select('element','Element',c.element,['Auto','Katon','Raiton','Suiton','Doton','Fuuton'])}${field('variation','Attack variation',c.variation,'number','min="0" max="999999" step="1" required')}</div></details><div class="buttons sectiongap"><button class="primary" type="submit">Forge monster ↗</button><button type="button" data-do="random-seed">New seed</button><button type="button" data-do="reroll-actions">Reroll moves</button></div><p class="formhint">Same inputs, same creature. Combat never rerolls the profile. Forging a new creature archives an active hunt in your bestiary.</p><div id="forge-error" role="alert"></div></form></section>${profilePanel()}</div><div class="toolbar sectiongap"><h2>The creature’s repertoire</h2><a href="#combat">Open combat screen ↗</a></div>${actions(false)}`;}
function actionCard(a,combat){const ready=availability(a,profile,state.battle,live,decl.noEarth),base=baseEffort(a,profile,decl.noEarth),effort=base+(live.gates>=2&&base>=2?1:0);return `<article class="panel action"><div class="topline"><span class="badge">${a.jutsu?'JUTSU':'MOVE '+a.slot} / ${a.effort>=2?'HEAVY':'NORMAL'}</span>${combat?`<span class="badge ${ready==='Ready'?'green':'red'}">${esc(ready)}</span>`:''}</div><h3>${esc(a.name)}</h3><p class="muted">${esc(a.reach)} · ${esc(a.type)}</p><div class="quick"><span>Spd <strong>${a.speed}</strong></span><span>${a.jutsu?'Channel':'Delay'} <strong>${a.delay}</strong></span><span>Effort <strong>${combat?effort:a.effort}</strong></span><span>ACC <strong>${signed((combat?live.accuracy:profile.accuracy)+a.acc)}</strong></span></div><div class="roll">${esc(damageExpression(a,profile))}</div><p class="effect">${esc(a.effect)}</p><details><summary>Telegraph, timing & counterplay</summary><p><strong>Tell:</strong> ${esc(a.tell)}</p><p><strong>Counter:</strong> ${esc(a.counter)}</p><p><strong>Required part:</strong> ${esc(profile.parts[a.part])}. Cooldown ${a.cooldown} IC.</p><p>Declare IC ${state.battle.ic}. Resolve IC ${state.battle.ic+a.delay}. Next IC ${state.battle.ic+a.speed+(a.jutsu?a.delay:0)}. Max interrupt Speed ${Math.floor(a.speed/2)}.</p>${a.jutsu?`<p><a href="${esc(a.source)}" target="_blank" rel="noopener">Read source jutsu ↗</a></p>`:''}</details><div class="buttons"><button class="small" data-do="copy-action" data-slot="${a.slot}">Copy declaration</button><button class="small" data-do="copy-roll" data-slot="${a.slot}">Copy roll</button>${combat?`<button class="small primary" data-do="declare" data-slot="${a.slot}" ${ready!=='Ready'||state.battle.ic<state.battle.next?'disabled':''}>Declare move</button>`:''}</div></article>`;}
function actions(combat=true){return `<div class="cards">${profile.actions.map(a=>actionCard(a,combat)).join('')}</div>`;}
function stateCards(){return `<div class="stategrid"><section class="panel statecard"><small>INJURY / ${live.gates} OF 6 GATES</small><div class="state">${live.injury}</div><div class="segments" role="meter" aria-label="Injury gates crossed" aria-valuemin="0" aria-valuemax="6" aria-valuenow="${live.gates}">${Array.from({length:6},(_,i)=>`<span class="${i<live.gates?'filled':''}"></span>`).join('')}</div><small>${live.nextGate} damage to next gate · ${profile.gate} per gate</small></section><section class="panel statecard"><small>ENERGY / ${live.exertion} OF 10 EXERTION</small><div class="state">${live.energy}</div><div class="segments exertion" role="meter" aria-label="Exertion" aria-valuemin="0" aria-valuemax="10" aria-valuenow="${live.exertion}">${Array.from({length:10},(_,i)=>`<span class="${i<live.exertion?'filled':''}"></span>`).join('')}</div><small>Roll penalty −${live.penalty} · Recovery floor ${live.floor}${live.spentUntil?' · Spent until IC '+live.spentUntil:''}</small></section></div>`;}
function combat(){return intro('02 / LIVE HUNT',esc(profile.name),'All the numbers you need for the next declaration. Log resolved damage, advance Initiative Count, and keep the hunt moving.')+stateCards()+panel('The field clock',`<div class="combatbar no-print"><div class="clock">${state.battle.ic}<small> CURRENT IC</small></div><button data-do="advance" data-amount="1">+1 IC</button><button data-do="advance" data-amount="5">+5 IC</button><button data-do="next-action">Next action</button>${field('set-ic','Go to IC',state.battle.ic,'number','min="0" step="1"')}${field('next-ic','Next action IC',state.battle.next,'number','min="0" step="1"')}</div><p class="formhint">${live.gates===6?'Felled: adjudicate the outcome. Capture is not automatic.':live.exertion===10?'Spent: physically possible defenses remain legal. No normal actions until collapse ends.':state.battle.ic>=state.battle.next?'The monster can take its next normal action.':'Next normal action at IC '+state.battle.next+'. Interrupts add to that time.'}</p>${metrics({'Current Accuracy':signed(live.accuracy),'Defense bonus':signed(live.defense),'Move yd / IC':live.movement,'Physical DR':live.dr,'Grapple Offense':live.grappleOff,'Grapple Def bonus':live.grappleDef})}`)+`<div class="split sectiongap">${panel('Log incoming damage',`<form id="damage-form"><div class="formgrid">${field('damage','Damage after mitigation',0,'number','min="0" step="any" required')}${select('hit-part','Location hit',profile.parts[0],profile.parts)}${field('wounding','Wounding-only bonus %',0,'number','min="0" max="1000" step="any"')}<div class="field"><label class="check"><input id="targeted" type="checkbox"> Targeted hit / Called Shot</label><label class="check"><input id="includes-weakspot" type="checkbox"> Damage already includes weakspot +25%</label></div></div><button class="primary sectiongap" type="submit">Record damage</button><p class="formhint">Open wound + targeted hit adds 25% once. Opening hits give no break progress. Wounding-only bonuses affect opening / break progress, never gate damage. Area damage hits the creature once.</p></form>`)}${panel('Declarations & interrupts',`<div class="formgrid">${field('target','Declaration target',decl.target,'text','maxlength="160"')}${select('decl-format','Declaration format',decl.format,['plain','macro'])}<label class="check full"><input id="no-earth" type="checkbox" ${decl.noEarth?'checked':''}> Doton has no available earth (+5 Chakra)</label></div><div class="buttons sectiongap"><button data-do="dodge">Dodge · Speed 2</button><button data-do="parry">Parry · Speed 3</button><button data-do="abort-channel">Abort channel · Speed 1</button><button data-do="shake">Shake Off · Speed 8</button></div><details><summary>Exertion, recovery & external effects</summary><form id="effort-form"><div class="formgrid sectiongap">${field('effort-delta','Exertion change',1,'number','step="1" required')}${field('effort-note','Reason','External exertion','text','maxlength="200"')}</div><button class="sectiongap" type="submit">Log exertion change</button></form><div class="buttons sectiongap"><button data-do="catch-breath">Start Catch Breath</button><button data-do="complete-breath">Complete Catch Breath</button></div><p class="formhint">Catch Breath: Speed 10 / Delay 10; recover 3 only if uninterrupted. External Fatigue +1 → Exertion +2. Each 20 IC, larger STM/CE penalty: +1 per 5, max +2. Basic defenses add no Exertion.</p></details>`)} </div><div class="toolbar sectiongap"><h2>Available repertoire</h2><button data-do="copy-state">Copy combat status</button></div>${actions()}<div class="sectiongap">${capturePanel()}</div><div class="sectiongap no-print">${weaponPanel()}</div><div class="sectiongap">${eventLog()}</div>`;}
function capturePanel(){const c=live.capture;const text=c?c.invalid?'Attempt interrupted / invalid':c.confirmed?'Capture confirmed':state.battle.ic>=c.ends?'Timer complete — confirm uninterrupted capture':`${c.ends-state.battle.ic} IC remaining`:'No capture attempt started';return panel('Capture protocol',`<p><span class="badge ${live.captureReady?'green':'red'}">${live.captureReady?'CAPTURE-READY':'PREREQUISITES INCOMPLETE'}</span></p><p>Exactly five Injury Gates and Exertion 8+, an appropriate restraint, and a prepared capture kit. Secure Capture takes 10 IC. Consume one charge when starting; all prerequisites must hold throughout.</p><div class="buttons no-print"><label class="check"><input id="restraint" type="checkbox" ${live.restraint?'checked':''}> Appropriate restraint holds</label><label class="check"><input id="gear" type="checkbox" ${live.gear?'checked':''}> Capture kit ready</label></div><p class="timer sectiongap">${text}${c?' · began IC '+c.start+' · ends IC '+c.ends:''}</p><div class="buttons no-print"><button data-do="capture-start" ${!live.captureReady||state.battle.ic<state.battle.next?'disabled':''}>Start Secure Capture</button><button data-do="capture-interrupt" ${!c||c.invalid||c.confirmed?'disabled':''}>Mark interrupted</button><button data-do="capture-confirm" ${!c||c.invalid||c.confirmed||state.battle.ic<c.ends||!live.captureReady?'disabled':''}>Confirm held throughout</button></div><p class="formhint">The log checks injury, exertion and equipment continuity. Confirm physical restraint continuity yourself. Felled does not automatically mean dead or captured. Colony and Calamity captures require the stated scenario conditions.</p>`);}
function eventLog(){return panel('Chronological battle log',`<div class="toolbar no-print"><p class="muted">${state.battle.events.length} entries · ${live.damage} total gate damage</p><div class="buttons"><button data-do="undo" ${state.battle.events.length?'':'disabled'}>Undo last added event</button><button data-do="reset-battle">Archive & reset battle</button></div></div>${state.battle.events.length?`<div class="tablewrap" tabindex="0" role="region" aria-label="Battle log"><table><thead><tr><th>IC</th><th>Event</th><th>Details</th><th>State</th></tr></thead><tbody>${[...state.battle.events].sort((a,b)=>b.ic-a.ic||b.id-a.id).map(e=>`<tr><td>${e.ic}</td><td>${esc(e.type)}</td><td>${esc(e.type==='Damage'?e.amount+' damage to '+profile.parts[e.part]+(e.targeted?' (targeted)':''):e.type==='Action'?profile.actions.find(a=>a.slot===e.slot)?.name:e.type==='Break'?profile.parts[e.part]:e.amount??e.note??e.value??'')}</td><td>${e.ic>state.battle.ic?'Pending':'Resolved'}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">The hunt is quiet. Declare a move or record the first hit.</div>`}`);}
function parts(){return intro('03 / WEAKSPOTS & GRIP','Find the <em>opening.</em>','Wounds last 20 IC, including the expiry count. Follow-up hits earn permanent breaks. Each climber holds their own Control.')+`<div class="toolbar"><p class="muted">Current IC ${state.battle.ic} · Opening / break threshold ${profile.breakThreshold}</p><a href="#combat">Record damage in combat ↗</a></div><div class="cards">${live.parts.map((part,i)=>`<article class="panel partcard"><span class="partnum">PART ${i+1}</span><h3>${esc(part.name)}</h3><span class="badge ${part.window==='Open'||part.window==='Break ready'?'red':''}">${part.window}</span><p class="sectiongap">${part.opened===null?'No open wound.':`Opened IC ${part.opened} · expires IC ${part.opened+20}`}</p><div class="bar"><span style="width:${Math.min(100,part.progress/profile.breakThreshold*100)}%"></span></div><p class="muted">${part.progress} / ${profile.breakThreshold} break progress</p><p class="formhint">${esc(i===0?'Head break: Accuracy −1. Disable head-linked moves.':i===1?(state.config.tribe==='Sky'?'Wing break ends flight. Land and adjudicate falling normally.':'Locomotion break: movement −20%. Disable linked moves.'):i===2?'Outer break removes physical DR and disables linked moves.':'Core break disables core-linked moves and traits. Capture remains possible.')}</p><button data-do="break-part" data-part="${i}" ${part.window!=='Break ready'?'disabled':''}>Confirm permanent break</button></article>`).join('')}</div><div class="sectiongap">${panel('Clinging hunters',`${!profile.climbable?'<div class="notice">This profile is not climbable by default. Use ordinary grappling.</div>':'<p class="muted">Connected route: 1 ↔ 2 ↔ 3 ↔ 4. Positive Control belongs to the hunter, negative to the monster. Eject at −5.</p>'}<form id="climber-form" class="no-print"><div class="formgrid">${field('climber-name','Hunter name','','text','required maxlength="80"')}${select('climber-part','Starting part',profile.parts[0],profile.parts)}${field('climber-control','Starting signed Control',0,'number','step="1" required')}${field('pressure','Pressure ranks',0,'number','min="0" max="100" step="1" required')}</div><button class="sectiongap" type="submit" ${profile.climbable?'':'disabled'}>Add climber</button></form>${state.battle.climbers.map((c,i)=>`<article class="listrow"><div><h3>${esc(c.name)} <span class="badge">${c.control<=-5?'EJECTED':'CLINGING'}</span></h3><p class="muted">Part ${c.part+1}: ${esc(profile.parts[c.part])} · Control ${c.control} / ±${c.max} · next IC ${c.next}</p></div><div class="buttons no-print"><button class="small" data-do="grip" data-index="${i}" ${c.control<=-5?'disabled':''}>Secure Grip success +3</button><button class="small" data-do="shake-climber" data-index="${i}" ${c.control<=-5?'disabled':''}>Shake Off success −3</button><button class="small" data-do="clamber-back" data-index="${i}" ${c.part===0||c.control<2?'disabled':''}>Clamber ←</button><button class="small" data-do="clamber-forward" data-index="${i}" ${c.part===3||c.control<2?'disabled':''}>Clamber →</button><button class="small" data-do="edit-control" data-index="${i}">Adjust Control</button><button class="small" data-do="release" data-index="${i}">Release</button></div></article>`).join('')}<details class="sectiongap"><summary>Grip action declarations & restrictions</summary>${gripTemplates().map((t,i)=>`<div class="copyblock sectiongap"><p>${esc(t)}</p><button class="small" data-do="copy-grip" data-index="${i}">Copy</button></div>`).join('')}<p class="formhint">Secure Grip buttons assume a successful opposed roll. Clamber needs 2 positive Control. Hunter actions lose floor(Speed / 3) Control, damage greater than RES / 4 and wounds lose Control normally; use Adjust Control. One hand grips, hunter Dodge/Parry Base Speed +2, monster movement remains unhalved. Dodging away or teleporting ends Cling. No pooled Control.</p></details>`)} </div><div class="sectiongap">${statusesPanel()}</div>`;}
function gripTemplates(){return ['(**Grab**: Stamina 8 + 2 per prior successful grapple, Spd: 12, ACC +2). Resolve opposed starting Control normally.','(**Secure Grip**: Stamina 5, Spd: 5, Control cost 0). Grapple Offense vs Defense; success shifts 3 Control toward hunter.','(**Clamber**: Stamina 8, Spd: 6, Control cost 2). Requires 2 positive Control; move to one adjacent part.','(**Shake Off**: Exertion 1, Spd: 8). Monster Grapple Offense vs each climber’s Defense; success shifts 3 toward monster, eject at monster Control 5+.','(**Release**: Spd: 0 on your action). End Cling. Called Shot to occupied part starts at −2.'];}
function statusesPanel(){return panel('Status & limited trait timers',`<p class="muted">Track the reminder here; apply printed status effects and damage cadence through the combat log.</p><form id="status-form" class="no-print"><div class="formgrid">${field('status-name','Status or trait','','text','required maxlength="100"')}${field('severity','Severity / uses',1,'number','min="0" max="1000" step="1" required')}${field('status-start','Started IC',state.battle.ic,'number','min="0" step="1" required')}${field('status-duration','Duration IC',20,'number','min="0" max="100000" step="1" required')}<div class="full">${field('status-note','Source / notes','','text','maxlength="400"')}</div></div><button class="sectiongap" type="submit">Track status</button></form>${state.battle.statuses.map((s,i)=>`<div class="listrow"><div><strong>${esc(s.name)} ${s.severity}</strong><p class="muted">${s.start>state.battle.ic?'Future':state.battle.ic>s.start+s.duration?'Expired':s.start+s.duration-state.battle.ic+' IC left'} · ${esc(s.note)}</p></div><button class="small no-print" data-do="remove-status" data-index="${i}">Remove</button></div>`).join('')}`);}
function announcement(){const h=state.hunt;return `HUNT ${state.config.seed}\nTarget: a chakra-active ${profile.body.toLowerCase()}\nClassification: ${state.config.threat}\nLast seen: ${h.location}\nSituation: ${h.incident}\nObjective: ${h.objective}\nFurther information must be earned through investigation.`;}
function hunt(){const h=state.hunt;return intro('04 / RESEARCH & BRIEFING','Before the <em>hunt.</em>','Prepare clues, plan the objective, and publish a briefing that keeps the creature’s combat secrets in the field manual.')+`<div class="split">${panel('Mission details',`<form id="hunt-form"><div class="formgrid"><div class="full">${field('location','Last seen',h.location,'text','maxlength="300"')}</div><div class="full">${field('incident','Incident',h.incident,'text','maxlength="500"')}</div><div class="full">${select('objective','Mission objective',h.objective,['Capture','Slay','Repel','Research','Rescue','Contain'])}</div>${field('tracks','Tracks Intel',h.tracks,'number','min="0" max="100" step="1"')}${field('nature','Nature Intel',h.nature,'number','min="0" max="100" step="1"')}${field('weakness','Weakness Intel',h.weakness,'number','min="0" max="100" step="1"')}<div class="full"><label for="preparations">Agreed preparations & owners</label><textarea id="preparations" name="preparations" rows="5" maxlength="5000">${esc(h.preparations)}</textarea></div></div><button class="primary sectiongap" type="submit">Save hunt preparation</button></form>`)}${panel('Player announcement',`<p class="formhint">Safe to share before investigation. No mutation, moves, numbers or weaknesses.</p><textarea class="codearea" rows="9" readonly aria-label="Player announcement">${esc(announcement())}</textarea><button class="sectiongap" data-do="copy-announcement">Copy announcement</button><details class="sectiongap"><summary>GM research clues & salvage</summary><p class="sectiongap"><strong>Tracks:</strong> ${esc(n(h.tracks)>0?profile.tracks:'Tracks not studied.')}</p><p><strong>Nature:</strong> ${esc(n(h.nature)>0?profile.identity:'Nature not researched.')}</p><p><strong>Weakness:</strong> ${esc(n(h.weakness)>0?profile.counter:'Weakness not studied.')}</p><p><strong>Salvage:</strong> ${esc(profile.salvage)}</p><p><strong>Role tactics:</strong> ${esc(profile.tactics)}</p></details>`)} </div><div class="sectiongap">${panel('GM encounter notes',`<label for="gm-notes">Terrain, objectives, restraint escape conditions, rewards and rulings</label><textarea id="gm-notes" rows="7" maxlength="15000">${esc(state.notes||'')}</textarea><p class="formhint">Notes and full-sheet share links include GM information. Use the player announcement for public briefings.</p>`)}</div>`;}
function bestiary(){return intro('05 / SAVED CREATURES','Your field <em>bestiary.</em>','Keep reusable profiles and finished hunts. Everything stays in this browser; export JSON for backups or another device.')+`<div class="toolbar"><div class="buttons"><button class="primary" data-do="save-monster">Save current monster</button><button data-do="export">Export current JSON</button><button data-do="export-library" ${library.length?'':'disabled'}>Export bestiary</button></div><div><label for="import-file">Import a sheet or bestiary (.json)</label><input id="import-file" type="file" accept=".json,application/json"></div></div><div class="cards">${library.length?library.map((item,i)=>`<article class="panel bestcard"><span class="badge">${esc(item.config.tribe)} / ${esc(item.config.threat)}</span><h3>${esc(generate(item.config).name)}</h3><p class="muted">Seed ${item.config.seed} · ${item.battle.events.length} battle events<br>${esc(new Date(item.savedAt).toLocaleString())}</p><div class="buttons"><button class="primary" data-do="load-monster" data-index="${i}">Open sheet</button><button data-do="export-item" data-index="${i}">Export</button><button data-do="delete-monster" data-index="${i}">Delete</button></div></article>`).join(''):'<div class="panel empty full">Your bestiary is empty. Save a creature from the forge to begin.</div>'}</div>`;}
function rules(){return intro('06 / FIELD REFERENCE','Know the <em>rules.</em>','Rules for wild monsters, hunting, capture, and combat. Browse the move library and adversary compendium.')+`<div class="toolbar"><div class="searchfield"><label for="rule-search">Search rules, moves & references</label><input type="search" id="rule-search" placeholder="Try capture, climbing, fatigue…"></div><select id="rule-category" aria-label="Reference category"><option value="rules">Monster Forge rules</option><option value="actions">All 120 moves & jutsu</option><option value="tribes">Tribes, classes & bodies</option><option value="legacy">Adversary compendium</option></select></div><p class="formhint">Wild hunt monsters only. Player characters and Tamed Monsters retain their source rules. Conditional traits and status effects require GM adjudication.</p><div id="rule-results" class="sectiongap">${ruleResults('rules','')}</div>`;}
let legacy=null;
function ruleResults(category,query){const q=query.toLowerCase();const matches=o=>JSON.stringify(o).toLowerCase().includes(q);
 if(category==='rules')return `<div class="rulelist">${DATA.rules.filter(matches).map(r=>`<article class="panel rulecard"><h3>${esc(r.title)}</h3><p>${esc(r.text).replace(/(https:\/\/[^\s]+)/g,'<a href="$1" target="_blank" rel="noopener">$1</a>')}</p></article>`).join('')||'<p>No matching rules.</p>'}</div>`;
 if(category==='actions')return `<div class="rulelist">${DATA.actions.filter(matches).map(a=>`<article class="panel rulecard"><span class="badge">${esc(a[0])}</span><h3 class="sectiongap">${esc(a[1])}</h3><p>Speed ${a[2]} · Delay / channel ${a[3]} · Exertion ${a[4]} · Cooldown ${a[5]}\n${esc(a[6])} / ${esc(a[7])}\n${esc(a[11])}\nTell: ${esc(a[12])}\nCounter: ${esc(a[13])}\nPart ${a[14]} · ${esc(a[15])}</p></article>`).join('')||'<p>No matching moves.</p>'}</div>`;
 if(category==='tribes')return `<h2>Combat classes</h2><div class="class-gallery sectiongap">${DATA.roles.filter(matches).map(r=>`<article class="panel class-card">${emblem('classes',r[0])}<h3>${esc(r[0])}</h3><p>${esc(r[10])}</p></article>`).join('')}</div><h2 class="sectiongap">Tribes & bodies</h2><div class="rulelist sectiongap">${DATA.tribes.filter(matches).map(t=>`<article class="panel rulecard"><h3 class="emblem-title">${emblem('tribes',t[0])}${esc(t[0])}</h3><p>${esc(t[16])}\nBodies: ${esc(t.slice(1,6).filter(Boolean).join(', '))}\nRoles: ${esc(t.slice(7,10).join(', '))}\nMutations: ${esc(t.slice(10,14).join(', '))}\n${esc(t[19])}</p></article>`).join('')}${DATA.bodies.filter(matches).map(b=>`<article class="panel rulecard"><h3>${esc(b[0])}</h3><p>${esc(b[1])}\nTerrain: ${esc(b[3])}\nSalvage: ${esc(b[2])}</p></article>`).join('')}</div>`;
 if(!legacy)return '<p>Loading the adversary compendium…</p>';
 return `<div class="notice">Adversary reference: mutation tiers, HP, Vitality, AP, and action costs. Wild hunt monsters use one mutation, Injury Gates, and Exertion.</div><div class="rulelist">${legacy.entries.filter(matches).map(r=>`<article class="panel rulecard"><span class="badge">${esc(r.category)}</span><h3 class="sectiongap">${esc(r.title)}</h3><p>${esc(r.text)}</p></article>`).join('')||'<p>No matching entries.</p>'}</div>`;
}
const views={forge,combat,parts,hunt,library:bestiary,rules};
function render(){refresh();view=(location.hash.slice(1).split('?')[0]||'forge');if(!views[view])view='forge';$('#view').innerHTML=views[view]();document.querySelectorAll('[data-view]').forEach(a=>{a.classList.toggle('active',a.dataset.view===view);if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#theme').textContent=document.documentElement.dataset.theme==='light'?'Dark mode':'Light mode';$('#readability').setAttribute('aria-pressed',String(document.body.classList.contains('large')));document.title=`${view==='forge'?'Forge a monster':view==='library'?'Bestiary':profile.name} · MonsterForge`;}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied to clipboard.');}catch{$('#copy-text').value=text;$('#copy-dialog').showModal();$('#copy-text').select();}}
function snapshot(){return JSON.parse(JSON.stringify({...state,savedAt:new Date().toISOString()}));}
function archive(){library.unshift(snapshot());save();}
function download(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function filename(){return profile.name.replace(/[^a-z0-9]+/gi,'-').toLowerCase();}
function event(e){addEvent(state.battle,{ic:state.battle.ic,...e});save();render();}
function summary(){return `**${profile.name}** — ${state.config.threat} / ${state.config.tribe}\nIC ${state.battle.ic} | Next action IC ${state.battle.next}\n${live.injury}: ${live.gates}/6 gates | ${live.energy}: ${live.exertion}/10 Exertion\nACC ${signed(live.accuracy)} | Defense ${signed(live.defense)} | Move ${live.movement} yd/IC | Physical DR ${live.dr}\n${live.parts.map(p=>p.name+': '+p.window).join(' | ')}`;}
function setForge(random=false,moves=false){const f=$('#forge-form');if(!f.reportValidity())return;const fd=new FormData(f),c=Object.fromEntries(fd);for(const k of ['seed','xp','hunters','enemies','variation'])c[k]=n(c[k]);if(random)c.seed=crypto.getRandomValues(new Uint32Array(1))[0]%999999+1;if(moves)c.variation=state.config.variation+1;
 try{generate(c);if(state.battle.events.length||state.battle.climbers.length||state.battle.statuses.length)archive();state.config=c;state.battle=blankBattle();save();render();toast(moves?'New move variation forged. Previous active hunt archived.':'Monster forged.');}catch(e){$('#forge-error').innerHTML=`<p class="notice error">${esc(e.message)}</p>`;}}
document.addEventListener('submit',e=>{
 const f=e.target;if(!f.id||!f.matches('form'))return;e.preventDefault();
 try{
  if(f.id==='forge-form')return setForge();
  if(f.id==='damage-form'){event({type:'Damage',amount:n($('#damage').value),part:profile.parts.indexOf($('#hit-part').value),wounding:n($('#wounding').value),targeted:$('#targeted').checked,includesWeakspot:$('#includes-weakspot').checked});return;}
  if(f.id==='effort-form'){const delta=n($('#effort-delta').value);if(!delta)throw Error('Enter a non-zero exertion change.');event({type:delta<0?'Recover':'Exertion',amount:delta,note:$('#effort-note').value});return;}
  if(f.id==='climber-form'){if(!profile.climbable)throw Error('This monster is not climbable.');const max=10+Math.ceil(n($('#pressure').value)/2);state.battle.climbers.push({name:$('#climber-name').value,part:profile.parts.indexOf($('#climber-part').value),control:Math.max(-max,Math.min(max,n($('#climber-control').value))),max,next:state.battle.ic});}
  if(f.id==='status-form')state.battle.statuses.push({name:$('#status-name').value,severity:n($('#severity').value),start:n($('#status-start').value),duration:n($('#status-duration').value),note:$('#status-note').value});
  if(f.id==='hunt-form'){state.hunt=Object.fromEntries(new FormData(f));for(const k of ['tracks','nature','weakness'])state.hunt[k]=n(state.hunt[k]);toast('Hunt preparation saved.');}
  save();render();
 }catch(err){toast(err.message);}
});
document.addEventListener('click',async e=>{
 const btn=e.target.closest('[data-do]');if(!btn)return;const action=btn.dataset.do,i=n(btn.dataset.index),slot=n(btn.dataset.slot),a=profile.actions.find(a=>a.slot===slot),b=state.battle;
 try{
  if(action==='random-seed'||action==='reroll-actions')return setForge(action==='random-seed',action==='reroll-actions');
  if(action==='copy-action')return copy(declaration(a,profile,b,live,decl));
  if(action==='copy-roll')return copy(damageExpression(a,profile));
  if(action==='copy-multithrow'){const text=multithrow({...profile,accuracy:live.accuracy},{weapon:$('#throw-weapon').value,count:n($('#throw-count').value),perWeapon:n($('#throw-bonus').value),senbonUser:$('#senbon-user').checked,senbonPermission:$('#senbon-permission').checked,format:decl.format});return copy(text);}
  if(action==='copy-custom'){const fd=new FormData($('#custom-form'));const text=`(**${fd.get('custom-name')}**: ${fd.get('custom-type')}, Spd: ${fd.get('custom-speed')}, Delay / channel: ${fd.get('custom-delay')}, Exertion: ${fd.get('custom-effort')}, ACC ${fd.get('custom-accuracy')}, Range / Area: ${fd.get('custom-range')})\n${fd.get('custom-dice')}\n${fd.get('custom-effect')}`;return copy(text);}
  if(action==='copy-state')return copy(summary());if(action==='copy-grip')return copy(gripTemplates()[i]);if(action==='copy-announcement')return copy(announcement());
  if(action==='save-monster'){archive();toast('Monster saved to your bestiary.');if(view==='library')render();return;}
  if(action==='export')return download(snapshot(),filename()+'.json');if(action==='export-library')return download({type:'monsterforge-bestiary',version:1,sheets:library},'monsterforge-bestiary.json');if(action==='export-item')return download(library[i],'monsterforge-'+library[i].config.seed+'.json');
  if(action==='print'){printSheet();return;}
  if(action==='share'){const bytes=new TextEncoder().encode(JSON.stringify(snapshot()));let str='';for(const byte of bytes)str+=String.fromCharCode(byte);const encoded=btoa(str);if(encoded.length>60000)throw Error('This hunt is too large for a practical share link. Export JSON instead.');return copy(location.origin+location.pathname+'#import='+encoded);}
  if(action==='load-monster'){const chosen=JSON.parse(JSON.stringify(library[i]));if(b.events.length)archive();state=validateImport(chosen);save();location.hash='#combat';render();toast('Saved sheet opened.');return;}
  if(action==='delete-monster'){const ok=await confirmAction('Delete saved monster?','This removes this saved copy from this browser. Export it first if you need a backup.');if(!ok)return;library.splice(i,1);save();render();return;}
  if(action==='reset-battle'){archive();state.battle=blankBattle();save();render();toast('Previous battle archived. Trackers reset.');return;}
  if(action==='advance'){b.ic+=n(btn.dataset.amount);save();render();return;}
  if(action==='next-action'){b.ic=Math.max(b.ic,b.next);save();render();return;}
  if(action==='declare'){
   if(availability(a,profile,b,live,decl.noEarth)!=='Ready'||b.ic<b.next)throw Error('This move is not available at the current IC.');const text=declaration(a,profile,b,live,decl);addEvent(b,{type:'Action',ic:b.ic+a.delay,slot:a.slot,noEarth:decl.noEarth,declared:b.ic});b.next=b.ic+a.speed+(a.jutsu?a.delay:0);save();render();await copy(text);return;
  }
  if(action==='dodge'||action==='parry'){b.next=Math.max(b.next,b.ic)+(action==='dodge'?2:3);if(b.breath)b.breath.spoiled=true;if(live.capture&&!live.capture.confirmed)addEvent(b,{type:'CaptureInterrupt',ic:b.ic});save();render();await copy(`(**${action==='dodge'?'Dodge':'Parry'}**: Spd: ${action==='dodge'?2:3}, defense bonus ${signed(live.defense)}). Next normal action IC ${b.next}.`);return;}
  if(action==='abort-channel'){const pending=b.events.find(e=>e.type==='Action'&&e.ic>b.ic&&profile.actions.find(a=>a.slot===e.slot)?.jutsu);if(!pending)throw Error('There is no active jutsu channel to abort.');b.events=b.events.filter(e=>e.id!==pending.id);b.next=b.ic+1;save();render();toast('Channel aborted. No jutsu Exertion applied. Next action IC '+b.next+'.');return;}
  if(action==='shake'){if(b.ic<b.next||live.exertion===10||live.gates===6)throw Error('Monster cannot take a normal action now.');b.next=b.ic+8;event({type:'Exertion',amount:1,note:'Shake Off: opposed check per climber'});return;}
  if(action==='catch-breath'){if(b.ic<b.next||live.exertion===10||live.gates===6)throw Error('Catch Breath is unavailable now.');b.breath={start:b.ic,end:b.ic+10,startId:Math.max(0,...b.events.map(e=>e.id)),spoiled:false};b.next=b.ic+10;save();render();toast('Catch Breath started. Advance to completion, then confirm no interruption.');return;}
  if(action==='complete-breath'){const breath=b.breath;if(!breath)throw Error('Start Catch Breath first.');if(b.ic<breath.end)throw Error('Catch Breath completes at IC '+breath.end+'.');if(breath.spoiled||b.events.some(e=>e.id>(breath.startId||0)&&e.ic>=breath.start&&e.ic<=breath.end&&['Damage','Action'].includes(e.type)))throw Error('Catch Breath was spoiled. Start a new attempt.');const ok=await confirmAction('Complete Catch Breath?','Confirm no damage, forced movement, action or interrupt spoiled this 10 IC attempt.');if(!ok)return;delete b.breath;event({type:'Recover',amount:-3,ic:breath.end,note:'Uninterrupted Catch Breath'});return;}
  if(action==='undo'){const max=Math.max(...b.events.map(e=>e.id));b.events=b.events.filter(e=>e.id!==max);save();render();toast('Last event removed. Review Next action IC manually.');return;}
  if(action==='break-part'){const part=n(btn.dataset.part);if(live.parts[part].window!=='Break ready')throw Error('The active wound has not earned a break.');event({type:'Break',part});return;}
  if(action==='capture-start'){if(!live.captureReady||b.ic<b.next)throw Error('Capture prerequisites are incomplete.');b.next=b.ic+10;event({type:'CaptureStart',note:'Consume one prepared capture charge'});toast('Capture attempt started. One prepared charge is consumed.');return;}
  if(action==='capture-interrupt')return event({type:'CaptureInterrupt'});if(action==='capture-confirm')return event({type:'CaptureConfirm'});
  const c=b.climbers[i];if(['grip','shake-climber','clamber-back','clamber-forward','edit-control','release'].includes(action)){
   if(action==='release')b.climbers.splice(i,1);
   else if(action==='edit-control'){const val=await numericInput(c.control);if(val===null)return;c.control=Math.max(-c.max,Math.min(c.max,val));}
   else if(action==='shake-climber')c.control=Math.max(-c.max,c.control-3);
   else{if(b.ic<c.next)throw Error('Hunter can act at IC '+c.next+'.');if(c.control<=-5)throw Error('This hunter was ejected.');if(action==='grip'){c.control=Math.min(c.max,c.control+3);c.next=b.ic+5;}else{if(c.control<2)throw Error('Clamber needs 2 positive Control.');c.part+=action==='clamber-back'?-1:1;c.part=Math.max(0,Math.min(3,c.part));c.control-=2;c.next=b.ic+6;}}save();render();return;
  }
  if(action==='remove-status'){b.statuses.splice(i,1);save();render();return;}
 }catch(err){toast(err.message);}
});
async function confirmAction(title,message){return new Promise(resolve=>{const d=$('#confirm-dialog');$('#confirm-title').textContent=title;$('#confirm-message').textContent=message;const finish=v=>{d.close();$('#confirm-ok').onclick=null;$('#confirm-cancel').onclick=null;d.oncancel=null;resolve(v);};$('#confirm-ok').onclick=()=>finish(true);$('#confirm-cancel').onclick=()=>finish(false);d.oncancel=e=>{e.preventDefault();finish(false);};d.showModal();$('#confirm-cancel').focus();});}
async function numericInput(value){const d=document.createElement('dialog');d.innerHTML=`<h2>Adjust signed Control</h2><p>Apply hunter action loss, wounds, incoming damage, or opposed roll results. Monster ejection threshold is −5.</p><form method="dialog"><label for="control-adjust">New signed Control</label><input id="control-adjust" type="number" value="${value}" step="1" required><div class="buttons"><button value="cancel" formnovalidate>Cancel</button><button value="save">Save Control</button></div></form>`;document.body.append(d);return new Promise(resolve=>{d.onclose=()=>{const v=d.returnValue==='save'?n(d.querySelector('input').value):null;d.remove();resolve(v);};d.showModal();d.querySelector('input').select();});}
function weaponPanel(){return panel('Additional declaration templates',`<details><summary>Multi-Throw</summary><p class="formhint">Requires suitable anatomy, carried weapons, and Multi-Throw permission. Set the damage bonus used by your campaign.</p><div class="formgrid sectiongap">${select('throw-weapon','Thrown weapon','Kunai',['Kunai','Shuriken','Senbon'])}${field('throw-count','Projectiles (DEX / 10 limit)',2,'number',`min="2" max="${Math.floor(profile.stats.DEX/10)}" step="1"`)}${select('throw-bonus','DB per kunai / shuriken','0.5',['0.5','0.25'])}<div><label class="check"><input id="senbon-user" type="checkbox"> Senbon User</label><label class="check"><input id="senbon-permission" type="checkbox"> Senbon Multi-Throw permission</label></div></div><button class="sectiongap" data-do="copy-multithrow">Copy Multi-Throw declaration</button><p class="formhint">Minimum Speed 5. Shuriken gain +2 Accuracy once per throw. For wild monsters, record the GM-assigned Exertion cost in the combat log.</p><a href="https://evilbaz.github.io/TheEmberCorps/rules/core/#multi-throw" target="_blank" rel="noopener">Read Multi-Throw rules ↗</a></details><details><summary>Custom move / jutsu</summary><form id="custom-form"><div class="formgrid sectiongap">${field('custom-name','Move name','Custom action','text','maxlength="100"')}${field('custom-type','Type / rank / element','Monster Action','text','maxlength="100"')}${field('custom-speed','Attack Speed',8,'number','min="0" step="1"')}${field('custom-delay','Delay / channel IC',0,'number','min="0" step="1"')}${field('custom-effort','Exertion cost',1,'number','min="0" max="10" step="1"')}${field('custom-accuracy','Final Accuracy',live.accuracy,'number','step="any"')}<div class="full">${field('custom-range','Range / area','Melee 2','text','maxlength="100"')}</div><div class="full">${field('custom-dice','Complete dice expression','[[2d6+('+profile.pdb+'*8)]]','text','maxlength="500"')}</div><div class="full"><label for="custom-effect">Effect and restrictions</label><textarea id="custom-effect" name="custom-effect" rows="3" maxlength="2000"></textarea></div></div><button class="sectiongap" type="button" data-do="copy-custom">Copy custom declaration</button><p class="formhint">Record custom moves with the Exertion log and Next action IC. Save their effects in GM notes.</p></form></details>`);}
function printSheet(){refresh();const previous=view;$('#view').innerHTML=intro('EMBER CORPS / MONSTER SHEET',esc(profile.name),`${esc(state.config.tribe)} · ${esc(state.config.threat)} · Seed ${state.config.seed}`)+profilePanel()+`<div class="sectiongap">${stateCards()}</div>`+panel('Live combat values',metrics({'Current IC':state.battle.ic,'Next action IC':state.battle.next,'Accuracy':live.accuracy,'Defense bonus':live.defense,'Movement yd / IC':live.movement,'Physical DR':live.dr}))+`<h2 class="sectiongap">Repertoire</h2>${actions(false)}<div class="sectiongap">${panel('Parts & hunt notes',live.parts.map(p=>`<p><strong>${esc(p.name)}:</strong> ${p.window} · ${p.progress} break progress</p>`).join('')+`<p>${esc(state.notes||'No additional GM notes.').replace(/\n/g,'<br>')}</p>`)}</div>`;$('#view').querySelectorAll('details').forEach(d=>d.open=true);window.addEventListener('afterprint',()=>{view=previous;render();},{once:true});window.print();}
document.addEventListener('change',async e=>{const el=e.target,b=state.battle;try{
 if(el.id==='set-ic'){const v=n(el.value);if(v<0||!Number.isInteger(v))throw Error('IC must be a non-negative whole number.');b.ic=v;save();render();}
 if(el.id==='next-ic'){const v=n(el.value);if(v<0||!Number.isInteger(v))throw Error('Next action IC must be a non-negative whole number.');b.next=v;save();}
 if(el.id==='target')decl.target=el.value;if(el.id==='decl-format')decl.format=el.value;if(el.id==='no-earth'){decl.noEarth=el.checked;render();}
 if(el.id==='restraint'||el.id==='gear')event({type:el.id==='restraint'?'Restraint':'Gear',value:el.checked});
 if(el.id==='gm-notes'){state.notes=el.value;save();}
 if(el.id==='rule-category'){if(el.value==='legacy'&&!legacy){const res=await fetch(new URL('./legacy.json',import.meta.url));if(!res.ok)throw Error('Original reference catalog could not load.');legacy=await res.json();}$('#rule-results').innerHTML=ruleResults(el.value,$('#rule-search').value);}
 if(el.id==='import-file'){const file=el.files[0];if(!file)return;if(file.size>5*1024*1024)throw Error('Import is limited to 5 MB.');const o=JSON.parse(await file.text());if(o.type==='monsterforge-bestiary'){if(o.version!==1||!Array.isArray(o.sheets)||o.sheets.length>500)throw Error('Invalid bestiary.');const sheets=o.sheets.map(validateImport);library.unshift(...sheets);save();render();toast('Bestiary imported.');}else{validateImport(o);if(b.events.length)archive();state=o;state.hunt={...{location:'',incident:'',objective:'Capture',tracks:0,nature:0,weakness:0,preparations:''},...o.hunt};save();location.hash='#combat';render();toast('Monster sheet imported.');}}
 }catch(err){toast(err.message);}});
document.addEventListener('input',e=>{if(e.target.id==='rule-search')$('#rule-results').innerHTML=ruleResults($('#rule-category').value,e.target.value);if(e.target.id==='gm-notes'){state.notes=e.target.value;save();}});
$('#theme').onclick=()=>{const t=document.documentElement.dataset.theme==='light'?'dark':'light';document.documentElement.dataset.theme=t;try{localStorage.setItem('mf-theme',t);}catch{}$('#theme').textContent=t==='light'?'Dark mode':'Light mode';};
$('#readability').onclick=()=>{document.body.classList.toggle('large');const v=document.body.classList.contains('large');$('#readability').setAttribute('aria-pressed',String(v));try{localStorage.setItem('mf-large',String(v));}catch{}};
function loadShared(){if(!location.hash.startsWith('#import='))return;try{const s=location.hash.slice(8);if(s.length>100000)throw Error('Share link too large.');const bytes=Uint8Array.from(atob(s),c=>c.charCodeAt(0));const o=validateImport(JSON.parse(new TextDecoder().decode(bytes)));if(state.battle.events.length)archive();state=o;save();history.replaceState(null,'',location.pathname+location.search+'#combat');toast('Shared monster opened. This sheet includes GM information.');}catch(e){history.replaceState(null,'',location.pathname+location.search+'#forge');toast('Share link could not load: '+e.message);}}
window.addEventListener('hashchange',()=>{loadShared();render();$('#main').focus({preventScroll:true});});loadShared();render();
